namespace ghidra.app.plugin.core.codebrowser.hover;

using static ghidra.util.HTMLUtilities;



using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra;
using ghidra.app.plugin.core.hover;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.program.util;

/**
 * A hover service to show the full namespace path of a symbol along with its symbol type and
 * source type.
 */
public class LabelListingHover : AbstractConfigurableHover, ListingHoverService {

	private static readonly string NAME = "Label Display";
	private static readonly string DESCRIPTION =
		"Toggle whether the full symbol name is shown as a tooltip.  This only applies " +
			"when displaying namespaces.";
	private static readonly int PRIORITY = 20;

	public LabelListingHover(PluginTool tool) : base(tool, PRIORITY)
    {
	}

	/* @Override */
	protected string getName() {
		return NAME;
	}

	/* @Override */
	protected string getDescription() {
		return DESCRIPTION;
	}

	/* @Override */
	protected string getOptionsCategory() {
		return GhidraOptions.CATEGORY_BROWSER_POPUPS;
	}

	/* @Override */
	public JComponent getHoverComponent(Program program, ProgramLocation programLocation,
			FieldLocation fieldLocation, Field field) {

		Symbol symbol = getLabelSymbol(programLocation);
		if (symbol == null) {
			return null;
		}
		return createTooltipComponent(getToolTipText(symbol));
	}

	private Symbol getLabelSymbol(ProgramLocation programLocation) {
		if (!enabled || programLocation == null) {
			return null;
		}

		if (!(programLocation is LabelFieldLocation)) {
			return null;
		}

		Symbol symbol = ((LabelFieldLocation) programLocation).getSymbol();
		if (symbol == null) {
			return null;
		}

		return symbol;
	}

	private string getToolTipText(Symbol symbol) {
		StringBuilder buf = new StringBuilder(HTML);
		buf.append(friendlyEncodeHTML(symbol.getName(true)));
		buf.append(BR).append(BR);
		buf.append("Type: ");
		buf.append(HTML_SPACE).append(HTML_SPACE).append(HTML_SPACE).append(HTML_SPACE);
		buf.append(symbol.getSymbolType());
		buf.append(BR);
		buf.append("Source: ");
		buf.append(symbol.getSource().getDisplayString());
		buf.append(BR);
		return buf.toString();

	}

}
